var comid = "";
var winwd = 0;
var winht = 0;

export default {
  data() {
    return {
      avtUrl: "",
      author: "",
      date: "",
      width: 0,
      height: 0,
      loopht: 0,
      desht: 0,
      name: "",
      des: "",
      price: 0,
      currency: "¥",
      loopimgs1: [],
      sliderht: 0,
      botht: 0,
      botbutwd: 0,
      botbutht: 0,
      botbutedge: 0,
      bothht: "",
      coll: ""
    };
  },

  components: {},
  props: {},

  onLoad() {
    var that = this;
    this.updateTuanInfoFromDB();
    var tmp = []; //取得全局App({..})实例

    comid = getApp().globalData.var1; //取得全局变量需要的值

    console.log('comdi' + comid);
    wx.getSystemInfo({
      success: function (res) {
        winwd = res.windowWidth;
        winht = res.windowHeight;
      }
    });
    this.setData({
      width: winwd,
      height: winht,
      loopht: winht * 0.4,
      desht: winwd * 0.28,
      sliderht: winht - winwd * 0.4 * 0.4,
      bothht: winht * 0.6,
      botht: winwd * 0.4 * 0.4,
      botbutwd: winwd * 0.4,
      botbutht: winwd * 0.4 * 0.4,
      botbutedge: winwd * 0.05
    });
    var iiii = comid;
    uni.request({
    	url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/getfromdb',
    	method:'POST',
      // 传给云函数的参数
      data: {
        target: 'secondHand',
        iddd: iiii,
        mode: 1
      },
      success: function (res) {
        console.log(res.data.Items[0]);
        that.setData({
          coll: res.data.Items[0],
          date: res.data.Items[0].date,
          avtUrl: res.data.Items[0].authorAva,
          author: res.data.Items[0].authorName
        });
      }
    });
  },

  methods: {
    updateTuanInfoFromDB() {
      var tmpInfo;
	  tmpInfo=getApp().globalData.itemInfo;
      this.setData({
        name: tmpInfo.name,
        des: tmpInfo.description,
        price: tmpInfo.price,
        loopimgs1: tmpInfo.img,
        currency: tmpInfo.currency
      });
    },

    buynow() {
      wx.navigateTo({
        url: '../payment/payment'
      });
    },

    atc() {},

    setData: function (obj, callback) {
      let that = this;
      let keys = [];
      let val, data;
      Object.keys(obj).forEach(function (key) {
        keys = key.split('.');
        val = obj[key];
        data = that.$data;
        keys.forEach(function (key2, index) {
          if (index + 1 == keys.length) {
            that.$set(data, key2, val);
          } else {
            if (!data[key2]) {
              that.$set(data, key2, {});
            }
          }

          data = data[key2];
        });
      });
      callback && callback();
    }
  }
};
